def remove_math_features(list_features):
    for i in list_features:
        df_math.drop(i,axis=1, inplace=True)
    return print("Features removed")

def remove_port_features(list_features):
    for i in list_features:
        df_port.drop(i,axis=1, inplace=True)
    return print("Features removed")
